mapper.select:
SELECT 
       FROM `diary` d LEFT JOIN `user` u ON d.user_id = u.id WHERE d.is_public = 1 ORDER BY
       d.like_count DESC, d.created_at DESC LIMIT #{limit}

mapper.update:
UPDATE `diary` SET title = #{title}, content =
       #{content}, cover = #{cover}, is_public = #{isPublic}, category = #{category}, tags =
       #{tags} WHERE id = #{id}

mapper.select:
SELECT DISTINCT DATE_FORMAT(created_at,
       '%Y-%m-%d') FROM `diary` WHERE user_id = #{userId} AND created_at >= #{from} AND
       created_at < #{to}
